function assert(value: unknown, message: string): void {
    if (!value) {
        throw new Error(message);
    }

}

import type { RolesApiPort } from '../ports.js';
/** Mutates a disposable, authenticated backend. Caller must hold role.manage and content.read.
 * Permission vocabulary can be supplied for another server's catalog. Cleanup failures are failures. */
export async function runRolesApiConformance({ api }: {
    api: RolesApiPort;
}, { permission = 'content.read', prefix = `conformance-${Date.now()}` }: {
    permission?: string;
    prefix?: string;
} = {}) {
    const passed: string[] = [], failed: {
        name: string;
        error: unknown;
    }[] = [];

    async function check(name: string, run: () => Promise<void>) {
        try {
            await run();
            passed.push(name);
        }
        catch (error) {
            failed.push({ name, error });
        }
    }
    let roleId: string | undefined, policyId: string | undefined, otherPolicyId: string | undefined, rowId: string | undefined;
    try {
        await check('create custom role', async () => { const { role } = await api.createRole({ name: `${prefix}-role` }); roleId = role.id; assert(!role.isBuiltin, 'created role must be custom'); });
        await check('list roles', async () => assert((await api.listRoles({})).roles.some(r => r.id === roleId), 'created role absent'));
        await check('update role', async () => { assert(roleId, 'create role failed'); assert((await api.updateRole({ roleId: roleId!, name: `${prefix}-renamed` })).role.name === `${prefix}-renamed`, 'rename missing'); });
        await check('snapshot isolation', async () => { const first = await api.listRoles({}); const r = first.roles.find(r => r.id === roleId); assert(r, 'role missing'); r!.name = 'mutated'; assert((await api.listRoles({})).roles.find(r => r.id === roleId)?.name === `${prefix}-renamed`, 'mutable adapter storage exposed'); });
        await check('create custom policy', async () => { const { policy } = await api.createPolicy({ name: `${prefix}-policy` }, { description: 'before' }); policyId = policy.id; assert(!policy.isBuiltin && !policy.isFrozen, 'created policy must be mutable'); });
        await check('list policies', async () => assert((await api.listPolicies({})).policies.some(p => p.id === policyId), 'created policy absent'));
        await check('partial update preserves name and clears description', async () => { assert(policyId, 'policy missing'); const { policy } = await api.updatePolicy({ policyId: policyId! }, { description: '' }); assert(policy.name === `${prefix}-policy` && policy.description === '', 'partial update lost fields'); });
        await check('write scoped permission', async () => { assert(policyId, 'policy missing'); const { policyPermission: p } = await api.writePolicyPermission({ policyId: policyId!, permission }, { resourceType: 'article' }); rowId = p.id; assert(p.policyId === policyId && p.permission === permission && p.resourceType === 'article', 'wrong permission record'); });
        await check('list permission ids', async () => assert((await api.listPolicyPermissions({ policyId: policyId! })).policyPermissions.some(p => p.id === rowId), 'permission absent'));
        await check('cross-policy removal fails closed', async () => {
            const { policy } = await api.createPolicy({ name: `${prefix}-other` }); otherPolicyId = policy.id; let rejected = false; try {
                await api.removePolicyPermission({ policyId: policy.id, policyPermissionId: rowId! });
            }
            catch {
                rejected = true;
            } assert(rejected, 'removed foreign policy permission'); assert((await api.listPolicyPermissions({ policyId: policyId! })).policyPermissions.some(p => p.id === rowId), 'foreign row lost');
        });
        await check('aborted writes do not persist', async () => {
            const abort = new AbortController(); abort.abort(); let rejected = false; try {
                await api.createRole({ name: `${prefix}-aborted` }, { signal: abort.signal });
            }
            catch {
                rejected = true;
            } assert(rejected, 'abort ignored'); assert(!(await api.listRoles({})).roles.some(r => r.name === `${prefix}-aborted`), 'aborted write persisted');
        });
        await check('remove permission', async () => { await api.removePolicyPermission({ policyId: policyId!, policyPermissionId: rowId! }); assert((await api.listPolicyPermissions({ policyId: policyId! })).policyPermissions.length === 0, 'removal absent'); });
        await check('policy deletion cascades own permissions', async () => { await api.writePolicyPermission({ policyId: policyId!, permission }); await api.deletePolicy({ policyId: policyId! }); assert(!(await api.listPolicies({})).policies.some(p => p.id === policyId), 'policy deletion absent'); policyId = undefined; });
    }
    finally {
        if (roleId) {
            await check('cleanup role', async () => { await api.deleteRole({ roleId: roleId! }); assert(!(await api.listRoles({})).roles.some(r => r.id === roleId), 'role deletion absent'); });
        }

        if (policyId) {
            await check('cleanup policy', async () => { await api.deletePolicy({ policyId: policyId! }); });
        }

        if (otherPolicyId) {
            await check('cleanup other policy', async () => { await api.deletePolicy({ policyId: otherPolicyId! }); });
        }

    }
    return { passed, failed };
}

import type { UsersApiPort,MembersApiPort,AuthApiPort } from '../ports.js';
/** Isolated disposable host required. User deletion moves to Trash; its retention cleanup belongs
 * to the host. Members are disable-only, so conformance takes a dedicated fixture id. */
export async function runUsersApiConformance({ api }: { api: UsersApiPort },{ prefix=`users-${Date.now()}`,roleId,policyId }: { prefix?: string; roleId?: string; policyId?: string }={}) {
  const passed: string[]=[],failed: { name: string; error: unknown }[]=[];

  const check=async (name: string,run: () => Promise<void>) => { try { await run(); passed.push(name); } catch(error) { failed.push({ name,error }); } };
  let principalId: string|undefined;
  try {
    await check('create operator',async () => { const { user }=await api.createUser({ username: prefix,password: 'test-secret' },{ email: 'before@example.test' }); principalId=user.principalId; assert(user.username===prefix.toLowerCase()&&user.status==='active','wrong created user'); });
    await check('list users roles policies and caller',async () => { const [u,r,p,me]=await Promise.all([api.listUsers({}),api.listRoles({}),api.listPolicies({}),api.me({})]); assert(u.users.some(u => u.principalId===principalId)&&Array.isArray(r.roles)&&Array.isArray(p.policies)&&me.user.id,'missing roster/caller'); });
    await check('snapshot isolation',async () => { const u=(await api.listUsers({})).users.find(u => u.principalId===principalId)!; (u.roleIds as string[]).push('foreign'); assert(!(await api.listUsers({})).users.find(u => u.principalId===principalId)!.roleIds.includes('foreign'),'mutable role storage exposed'); });
    await check('email patch preserves omitted email',async () => { await api.updateUser({ principalId: principalId! },{ email: 'after@example.test' }); assert((await api.updateUser({ principalId: principalId! })).user.email==='after@example.test','omitted email cleared'); });
    await check('disable and enable operator',async () => { assert((await api.disableUser({ principalId: principalId! })).user.status==='disabled','disable missing'); assert((await api.enableUser({ principalId: principalId! })).user.status==='active','enable missing'); });
    // eslint-disable-next-line sonarjs/no-hardcoded-passwords -- Disposable-user conformance fixture for an explicitly isolated authenticated host; this is not an application credential.
    await check('reset password',async () => { await api.resetUserPassword({ principalId: principalId!,password: 'replacement' }); });
    if(roleId) {
      await check('assign role',async () => { await api.assignRole({ principalId: principalId!,roleId }); assert((await api.listUsers({})).users.find(u => u.principalId===principalId)?.roleIds.includes(roleId),'role missing'); });
    }

    if(policyId) {
      await check('attach policy',async () => { await api.attachPolicy({ principalId: principalId!,policyId }); assert((await api.listUsers({})).users.find(u => u.principalId===principalId)?.policyIds.includes(policyId),'policy missing'); });
    }

    await check('aborted write does not persist',async () => { const abort=new AbortController(); abort.abort(); let rejected=false; try { await api.updateUser({ principalId: principalId! },{ email: 'bad@example.test',signal: abort.signal }); } catch { rejected=true; } assert(rejected&&(await api.listUsers({})).users.find(u => u.principalId===principalId)?.email==='after@example.test','abort ignored'); });
  } finally {
    if(principalId) {
      await check('delete moves out of roster',async () => { await api.deleteUser({ principalId: principalId! }); assert(!(await api.listUsers({})).users.some(u => u.principalId===principalId),'trashed user still listed'); });
    }

  }
  return { passed,failed };
}
export async function runMembersApiConformance({ api,memberId }: { api: MembersApiPort; memberId: string },_optional: Record<string,never>={}) {
  const passed: string[]=[],failed: { name: string; error: unknown }[]=[];

  const check=async (name: string,run: () => Promise<void>) => { try { await run(); passed.push(name); } catch(error) { failed.push({ name,error }); } };
  await check('list and read member',async () => { assert((await api.listMembers({})).members.some(m => m.id===memberId),'member absent'); assert((await api.getMember({ id: memberId })).member.id===memberId,'wrong member'); });
  await check('snapshot isolation',async () => { const { member }=await api.getMember({ id: memberId }); member.email='mutated@example.test'; assert((await api.getMember({ id: memberId })).member.email!==member.email,'mutable storage exposed'); });
  await check('constant magic-link response',async () => { assert((await api.requestMemberMagicLink({ email: 'unregistered@example.test' })).delivered===true,'enumeration response'); });
  await check('aborted disable does not persist',async () => { const before=(await api.getMember({ id: memberId })).member; const abort=new AbortController(); abort.abort(); let rejected=false; try { await api.disableMember({ id: memberId },{ signal: abort.signal }); } catch { rejected=true; } assert(rejected&&(await api.getMember({ id: memberId })).member.status===before.status,'abort ignored'); });
  await check('disable is idempotent',async () => { const first=(await api.disableMember({ id: memberId })).member,second=(await api.disableMember({ id: memberId })).member; assert(first.status==='disabled'&&second.status==='disabled'&&first.version===second.version,'non-idempotent disable'); });
  return { passed,failed };
}
export async function runAuthApiConformance({ api,credentials,expectedUserId }: { api: AuthApiPort; credentials: { username: string; password: string }; expectedUserId: string },_optional: Record<string,never>={}) {
  const passed: string[]=[],failed: { name: string; error: unknown }[]=[];
  const check=async (name: string,run: () => Promise<void>) => { try { await run(); passed.push(name); } catch(error) { failed.push({ name,error }); } };
  await check('login returns expected account',async () => {
    if((await api.login(credentials)).user.id!==expectedUserId) {
      throw new Error('wrong account');
    }
  });
  await check('empty password is rejected',async () => {
    let rejected=false; try { await api.login({ ...credentials,password: '' }); } catch { rejected=true; } if(!rejected) {
      throw new Error('empty password authenticated');
    }
  });
  await check('aborted login is rejected',async () => {
    const abort=new AbortController(); abort.abort(); let rejected=false; try { await api.login(credentials,{ signal: abort.signal }); } catch { rejected=true; } if(!rejected) {
      throw new Error('abort ignored');
    }
  });
  return { passed,failed };
}

import { useCallback, useEffect, useState, useSyncExternalStore } from 'react';
/** StrictMode gets a fresh effect-owned controller. Scope changes drop old data synchronously,
 * before the replacement effect runs; retired controllers abort requests and unsubscribe refresh. */
export function usePeopleController<S, C extends {
  getSnapshot(required?: Record<string, never>, optional?: Record<string, never>): S;
  subscribe(required: { listener: () => void }, optional?: Record<string, never>): () => void;
  dispose(required: Record<string, never>, optional?: Record<string, never>): void;
}>({ scope, key, create, start }: { scope: object; key: string; create: () => C; start: (controller: C) => void }, _optional: Record<string, never> = {}) {
  const [attachment, setAttachment] = useState<{ scope: object; key: string; controller: C } | null>(null);
  const controller = attachment?.scope === scope && attachment.key === key ? attachment.controller : null;
  useEffect(() => {
    const current = create(); setAttachment({ scope, key, controller: current }); start(current);
    return () => current.dispose({});
    // create/start are render closures; scope and key encode their entire injected dependency set.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scope, key]);
  const subscribe = useCallback((listener: () => void) => controller?.subscribe({ listener }) ?? (() => {}), [controller]);
  const read = useCallback(() => controller?.getSnapshot({}) ?? null, [controller]);
  const state = useSyncExternalStore(subscribe, read, () => null);
  return { controller, state };
}

import { useCallback, useEffect, useState, useSyncExternalStore } from 'react';
import { createRolesController } from '../../controllers/roles.controller.js';
import type { RolesController } from '../../controllers/roles.controller.js';
import { useRolesScope } from './RolesScope.hooks.js';
/** Controller creation belongs to the effect, so StrictMode replay gets a fresh instance.
 * Both tabs read the page-owned controller; neither tab starts its own duplicate fetches. */
export function useRolesController(_required: Record<string, never> = {}, _optional: Record<string, never> = {}) {
    const { api, permissions } = useRolesScope({});
    const grantKey = JSON.stringify(permissions);
    const [attachment, setAttachment] = useState<{
        controller: RolesController;
        api: typeof api;
        grantKey: string;
    } | null>(null);
    // A host/workspace swap cannot render the previous scope's data while its new effect attaches.
    const controller = attachment?.api === api && attachment.grantKey === grantKey ? attachment.controller : null;
    useEffect(() => {
        const current = createRolesController({ api }, { permissions });
        setAttachment({ controller: current, api, grantKey });
        void current.load({});
        return () => current.dispose({});
        // grantKey is the immutable grant value, independent of a Provider's object identity.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [api, grantKey]);
    const subscribe = useCallback((listener: () => void) => controller?.subscribe({ listener }) ?? (() => { }), [controller]);
    const read = useCallback(() => controller?.getSnapshot() ?? null, [controller]);
    const state = useSyncExternalStore(subscribe, read, () => null);
    return { controller, state, permissions };
}

import { useId } from "react";
import { SecretInput } from "@jini-ai/ui";
import type { AdminUser } from "../models.js";
import { useLogin, type LoginHookProps, type LoginOptions } from "./hooks/use-login.hooks.js";

export interface LoginProps extends LoginHookProps, LoginOptions {
  productName: string;
  onLogin: (user: AdminUser) => void;

  useLoginHook?: typeof useLogin | undefined;
}

export function Login({ onLogin, port, translate, productName, initialUsername, useLoginHook = useLogin }: LoginProps) {
  const { username, setUsername, password, setPassword, error, busy, submit, mfa } = useLoginHook({ onLogin, port, translate }, { initialUsername });
  const t = translate;
  const passwordInputId = useId();

  const readyLabel = mfa ? t("Verify code") : t("Sign in");
  const submitLabel = busy ? t("Signing in…") : readyLabel;

  return (
    <div className="login-screen">
      <form className="login-card" onSubmit={submit}>
        <h1>{productName}</h1>
        <p>{t("Sign in to your workspace")}</p>
        {mfa ? <>
        <p>{t("Enter a fresh code from your authenticator app. After setup, wait for the next code.")}</p>
        <label>
          {t("Authenticator code")}
          <input autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} data-agent-private="" value={mfa.code} onChange={e => mfa.setCode(e.target.value)} autoFocus />
        </label></> : <>
        <label>
          {t("Username")}
          <input autoComplete="username" value={username} onChange={(e) => setUsername(e.target.value)} autoFocus />
        </label>
        {/* A sibling label keeps the eye toggle's name out of the input's accessible name. */}
        <div>
          <label htmlFor={passwordInputId}>{t("Password")}</label>
          <SecretInput id={passwordInputId} label={t("Password")} toggleLabels={{ show: t("Show password"), hide: t("Hide password") }}
            autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} />
        </div>
        </>}
        {error ? <div className="login-error" role="alert">{error}</div> : null}
        <button disabled={busy}>{submitLabel}</button>
        {mfa ? <button type="button" disabled={busy} onClick={mfa.cancel}>{t("Cancel")}</button> : null}
      </form>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import type { Translate } from '@jini-ai/ui/panel-kit';
import type { PasskeyOptions } from '../../core/types.js';
import { runPasskeyCeremony } from './passkey-browser.js';

type Started = { pendingToken: string; options: PasskeyOptions };
type Finish = { pendingToken: string; response: unknown };
type Ceremony = typeof runPasskeyCeremony;
export interface PasskeySignInPort {
  begin(input: { pendingToken: string }): Promise<Started>;
  complete(input: Finish): Promise<void>;
}
export interface PasskeySettingsPort {
  status(): Promise<{ isOwner: boolean; credentials: { id: string }[] }>;
  enroll(input: { password: string; code: string }): Promise<Started>;
  confirm(input: Finish): Promise<void>;
  remove(input: { id: string; password: string; code: string }): Promise<void>;
}

/** Explicit alternative to a TOTP code; password proof remains required. O(1), two single-send calls. */
export function PasskeySignIn({ port, pendingToken, onComplete, translate: t, ceremony = runPasskeyCeremony }: {
  port: PasskeySignInPort; pendingToken: string; onComplete: () => void | Promise<void>; translate: Translate; ceremony?: Ceremony;
}) {
  const [busy, setBusy] = useState(false), [error, setError] = useState('');
  const generation = useRef(0);
  useEffect(() => () => { generation.current++; }, [pendingToken]);
  async function signIn() {
    const attempt = generation.current;
    setBusy(true); setError('');
    try {
      const started = await port.begin({ pendingToken });
      if (attempt !== generation.current) return;
      const response = await ceremony({ kind: 'authenticate', options: started.options });
      if (attempt !== generation.current) return;
      await port.complete({ pendingToken: started.pendingToken, response });
      if (attempt === generation.current) await onComplete();
    } catch (error) { if (attempt === generation.current) setError(error instanceof Error ? error.message : t('Passkey sign-in could not finish. Use your authenticator app or recovery code.')); }
    finally { if (attempt === generation.current) setBusy(false); }
  }
  return <div><button type="button" disabled={busy} onClick={signIn}>{t(busy ? 'Waiting for passkey…' : 'Use a passkey')}</button>
    {error ? <p role="alert">{error}</p> : null}</div>;
}

/** Settings use the same owner password/TOTP management policy, with public credential ids only.
 * @complexity O(n), n <= 5 credentials; one mount read and explicit single-send actions, no polling.
 */
export function PasskeySettings({ port, translate: t, ceremony = runPasskeyCeremony }: { port: PasskeySettingsPort; translate: Translate; ceremony?: Ceremony }) {
  const [status, setStatus] = useState<Awaited<ReturnType<PasskeySettingsPort['status']>>>();
  const [error, setError] = useState(''), [busy, setBusy] = useState(false);
  const [password, setPassword] = useState(''), [code, setCode] = useState('');
  useEffect(() => {
    let active = true;
    void port.status().then(value => { if (active) setStatus(value); }).catch(error => {
      if (active) setError(error instanceof Error ? error.message : t('Passkey settings could not load. Reload this page to try again.'));
    });
    return () => { active = false; };
  }, [port]);
  async function action(id?: string) {
    setBusy(true); setError('');
    try {
      if (id) await port.remove({ id, password, code });
      else {
        const started = await port.enroll({ password, code });
        const response = await ceremony({ kind: 'register', options: started.options });
        await port.confirm({ pendingToken: started.pendingToken, response });
      }
      setStatus(await port.status());
    } catch (error) { setError(error instanceof Error ? error.message : t('The passkey action could not finish. Try a new attempt.')); }
    finally { setPassword(''); setCode(''); setBusy(false); }
  }
  if (!status?.isOwner) return error ? <p role="alert">{error}</p> : null;
  return <section className="card"><h3>{t('Passkeys')}</h3>
    <p>{t('Use a passkey after your password instead of an authenticator code. Keep your authenticator app and recovery codes as a fallback.')}</p>
    <label>{t('Current owner password')}<input type="password" autoComplete="current-password" data-agent-private="" value={password} onChange={event => setPassword(event.target.value)} /></label>
    <label>{t('Authenticator code')}<input inputMode="numeric" autoComplete="one-time-code" maxLength={6} data-agent-private="" value={code} onChange={event => setCode(event.target.value)} /></label>
    <button type="button" disabled={busy || !password || !code || status.credentials.length >= 5} onClick={() => action()}>{t('Add passkey')}</button>
    <ul>{status.credentials.map((credential, index) => <li key={credential.id}>{t('Passkey')} {index + 1} <button type="button" disabled={busy || !password || !code} onClick={() => action(credential.id)}>{t('Remove passkey')} {index + 1}</button></li>)}</ul>
    {error ? <p role="alert">{error}</p> : null}
  </section>;
}

import { useEffect, useId, useState, type FormEvent } from 'react';
import { SecretInput } from '@jini-ai/ui';
import type { Translate } from '@jini-ai/ui/panel-kit';

export interface TotpSettingsPort {
  status(): Promise<{ isOwner: boolean; available: boolean; enrolled: boolean }>;
  enroll(input: { password: string; code?: string }): Promise<{ pendingToken: string; secret: string; uri: string }>;
  confirm(input: { pendingToken: string; code: string }): Promise<void>;
  remove(input: { password: string; code: string }): Promise<void>;
}
type Setup = Awaited<ReturnType<TotpSettingsPort['enroll']>>;

/** Owner settings hold setup secrets only until confirmation/cancellation or unmount.
 * @complexity O(1): one bounded status read on mount and one request per explicit action; no polling.
 */
export function TotpSettings({ port, translate: t }: { port: TotpSettingsPort; translate: Translate }) {
  const [status, setStatus] = useState<Awaited<ReturnType<TotpSettingsPort['status']>>>();
  const [error, setError] = useState('');
  useEffect(() => {
    let active = true;
    void port.status().then(value => { if (active) setStatus(value); }).catch(() => {
      if (active) setError(t('Authenticator settings could not load. Reload this page to try again.'));
    });
    return () => { active = false; };
  }, [port]);
  if (error) return <p role="alert">{error}</p>;
  if (!status?.isOwner || !status.available) return null;
  return <TotpSettingsForm port={port} enrolled={status.enrolled} t={t} />;
}

function TotpSettingsForm({ port, enrolled: initialEnrolled, t }: { port: TotpSettingsPort; enrolled: boolean; t: Translate }) {
  const [enrolled, setEnrolled] = useState(initialEnrolled), [setup, setSetup] = useState<Setup>();
  const [password, setPassword] = useState(''), [code, setCode] = useState('');
  const [busy, setBusy] = useState(false), [error, setError] = useState(''), [message, setMessage] = useState('');
  const passwordId = useId();
  function clear() { setSetup(undefined); setPassword(''); setCode(''); setError(''); }
  async function enroll(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError(''); setMessage('');
    try { setSetup(await port.enroll({ password, ...(enrolled ? { code } : {}) })); setCode(''); }
    catch (error) { setError(error instanceof Error ? error.message : t('Authenticator setup could not start. Try again.')); }
    finally { setPassword(''); setBusy(false); }
  }
  async function confirm(event: FormEvent) {
    event.preventDefault(); if (!setup) return;
    setBusy(true); setError('');
    try { await port.confirm({ pendingToken: setup.pendingToken, code }); clear(); setEnrolled(true); setMessage(t('Authenticator enabled. Sign in again with the next code from your app.')); }
    catch (error) { setError(error instanceof Error ? error.message : t('The code was not accepted. Enter a fresh authenticator code.')); }
    finally { setBusy(false); }
  }
  async function remove() {
    setBusy(true); setError(''); setMessage('');
    try { await port.remove({ password, code }); clear(); setEnrolled(false); setMessage(t('Authenticator removed. Sign in again.')); }
    catch (error) { setError(error instanceof Error ? error.message : t('The authenticator could not be removed. Check your password and code.')); }
    finally { setPassword(''); setCode(''); setBusy(false); }
  }
  return <section className="card">
    <h3>{t('Authenticator app')}</h3>
    <p>{t(enrolled ? 'Your authenticator code is required at every sign-in, including desktop.' : 'Add an authenticator app to require a code when signing in as the owner.')}</p>
    {setup ? <form onSubmit={confirm}>
      <p>{t('Add this setup key to your authenticator app, then enter its six-digit code. Keep the key private.')}</p>
      <code data-agent-private="">{setup.secret}</code>
      <CodeInput code={code} setCode={setCode} t={t} />
      <button disabled={busy}>{t('Confirm authenticator')}</button>
      <button type="button" disabled={busy} onClick={clear}>{t('Cancel')}</button>
    </form> : <form onSubmit={enroll}>
      <label htmlFor={passwordId}>{t('Current owner password')}</label>
      <SecretInput id={passwordId} label={t('Current owner password')} autoComplete="current-password" data-agent-private="" value={password} onChange={event => setPassword(event.target.value)} />
      <CodeInput code={code} setCode={setCode} t={t} visible={enrolled} />
      <button disabled={busy || !password}>{t(enrolled ? 'Replace authenticator' : 'Set up authenticator')}</button>
      {enrolled ? <button type="button" disabled={busy || !password || !code} onClick={remove}>{t('Remove authenticator')}</button> : null}
    </form>}
    {error ? <p role="alert">{error}</p> : null}
    {message ? <p role="status">{message}</p> : null}
  </section>;
}

function CodeInput({ code, setCode, t, visible = true }: { code: string; setCode: (code: string) => void; t: Translate; visible?: boolean }) {
  if (!visible) return null;
  return <label>{t('Authenticator code')}<input autoComplete="one-time-code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} data-agent-private="" value={code} onChange={event => setCode(event.target.value)} /></label>;
}

import { Fragment } from "react";
import { RowMenu, ConfirmDialog } from "@jini-ai/admin/react";
import { agentHandle } from "@jini-ai/agentic";
import type { AdminMember } from "../models.js";
import { formatTimestamp } from "@jini-ai/ui/panel-kit";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { buildAgentListHandles } from "@jini-ai/ui/panel-kit";

import { memberRowMenuItems, type RowActionState } from "./rules.js";
import { useMembers, type MembersDependencies, type MembersOptions } from "./hooks/use-members.hooks.js";
import type { ReactNode } from "react";

/**
 * @file Admin "Members" screen (ADR-030, ADR-PIPE-013 Decision §7) — markup only.
 *
 * State and API calls live in `hooks/use-members.hooks.ts`; the row-menu logic, per-row action
 * state shape, and the server-error-message override live in `rules.ts`. What stays here is what
 * actually renders: the table and the confirm dialog.
 *
 * Mirrors `features/posts/Posts.tsx`'s fetch/loading/error/table shape. Adds the
 * three row-level actions this remediation wires up (T039): disable, resend
 * sign-in link, and a click-to-expand detail panel — all calling the 3
 * already-existing, already-unused the host admin API client client methods
 * (`disableMember`, `requestMemberMagicLink`, `getMember`). No new backend
 * contract needed. Pagination is explicitly deferred (ADR-PIPE-013 Decision
 * §7) — not part of this screen yet.
 *
 * Per-row in-flight state disables only the clicked control (not the whole
 * table), and errors surface via the existing `notice error` convention
 * (inline per row for actions; a full-width banner for the initial load).
 * Stays a single flat file, matching every other admin section's convention.
 */
export interface MembersProps extends MembersDependencies, MembersOptions {
  useMembersHook?: typeof useMembers | undefined;
  /** Host terminology is copy, not a second members lifecycle. */
  description?: string | undefined;
  emptyDescription?: string | undefined;
  renderServerLabel?: ((required: { value: string }) => ReactNode) | undefined;
}

interface MemberDetailPanelProps {
  memberId: string;
  detailLoadingId: string | null;
  detailError: string | null;
  detail: AdminMember | undefined;
  t: Translate;
}

/** The expanded row's detail panel — one of "loading" / "error" / the fetched fields / nothing
 *  yet, extracted out of `MemberRow` so its three-way branch isn't counted in `MemberRow`'s own
 *  scope. Same "the panel, not the row, was the actual size" split `Users.tsx`'s
 *  `UserRow` -> `UserManagePanel` and `Roles.tsx`'s `PolicyRow` -> `PolicyRowActions` already use. */
function MemberDetailPanel({ memberId, detailLoadingId, detailError, detail, t }: MemberDetailPanelProps) {
  if (detailLoadingId === memberId) return <div className="notice">{t("Loading detail…")}</div>;
  if (detailError) return <div className="notice error">{detailError}</div>;
  if (!detail) return null;
  return (
    <dl className="member-detail">
      <dt>{t("ID")}</dt>
      <dd>{detail.id}</dd>
      <dt>{t("Email verified")}</dt>
      <dd>{detail.emailVerifiedAt ?? t("not verified")}</dd>
      <dt>{t("Updated")}</dt>
      <dd>{detail.updatedAt}</dd>
      <dt>{t("Version")}</dt>
      <dd>{detail.version}</dd>
    </dl>
  );
}

interface MemberRowProps {
  member: AdminMember;
  rowState: RowActionState;
  isExpanded: boolean;
  detail: AdminMember | undefined;
  detailError: string | null;
  detailLoadingId: string | null;
  onToggleDetail: (member: AdminMember) => Promise<void>;
  onResendSignInLink: (member: AdminMember) => Promise<void>;
  setConfirmingDisable: (member: AdminMember) => void;
  /** This row's own distinct handle base — computed once, across every rendered row, by `Members`
   *  (via `buildAgentListHandles`); see `Users.tsx`'s `UserRowProps.agentBase` for why a
   *  per-instance uniqueness search does not work here. */
  agentBase: string;
  t: Translate;
  translate: Translate;
  renderServerLabel?: MembersProps["renderServerLabel"];
}

/** One member's row plus its optional expanded detail row — extracted from `Members`'s
 *  `.map()` body verbatim, same convention `Users.tsx`'s `UserRow`/`Roles.tsx`'s `PolicyRow` use.
 *  `key` lives on the `<MemberRow>` element at the call site. */
function MemberRow({
  member,
  rowState,
  isExpanded,
  detail,
  detailError,
  detailLoadingId,
  onToggleDetail,
  onResendSignInLink,
  setConfirmingDisable,
  agentBase,
  t,
  translate,
  renderServerLabel,
}: MemberRowProps) {
  return (
    <Fragment key={member.id}>
      <tr>
        <td>
          <button
            type="button"
            className="link-button"
            onClick={() => void onToggleDetail(member)}
            aria-expanded={isExpanded}
            {...agentHandle({ handle: `${agentBase}-toggle-detail` }, { role: "button", label: `Expand or collapse ${member.email}'s detail panel` })}
          >
            {member.email}
          </button>
        </td>
        <td>{member.name ?? "—"}</td>
        <td>
          <span className={`status status-${member.status}`}>{renderServerLabel?.({ value: member.status }) ?? t(member.status)}</span>
        </td>
        <td>{formatTimestamp({ iso: member.createdAt })}</td>
        <td>
          <RowMenu
            triggerLabel={`${t("Actions for member")} "${member.email}"`}
            agentHandle={`${agentBase}-menu`}
            items={memberRowMenuItems({ member, rs: rowState, handlers: {
              onResendSignInLink: (m) => void onResendSignInLink(m),
              onRequestDisable: setConfirmingDisable,
            }, translate })}
          />
          {rowState.error ? (
            <div className="notice error" role="alert">
              {rowState.error}
            </div>
          ) : null}
          {rowState.notice ? <div className="notice">{rowState.notice}</div> : null}
        </td>
      </tr>
      {isExpanded ? (
        <tr>
          <td colSpan={5}>
            <MemberDetailPanel
              memberId={member.id}
              detailLoadingId={detailLoadingId}
              detailError={detailError}
              detail={detail}
              t={t}
            />
          </td>
        </tr>
      ) : null}
    </Fragment>
  );
}

export function Members({ useMembersHook = useMembers, port, translate: injectedTranslate, queryScope, refresh,
  description = "People who have registered an account — review status, resend a sign-in link, or disable access.",
  emptyDescription = "Registered members will show up here.", renderServerLabel }: MembersProps) {
  const {
    members,
    error,
    stateFor,
    onResendSignInLink,
    expandedId,
    detailById,
    detailError,
    detailLoadingId,
    onToggleDetail,
    confirmingDisable,
    setConfirmingDisable,
    confirmDisable,
    t,
    translate,
  } = useMembersHook({ port, translate: injectedTranslate, ...(queryScope === undefined ? {} : { queryScope }) }, { refresh });

  if (error) return <div className="notice error">{error}</div>;
  if (!members) return <div className="notice">{t("Loading members…")}</div>;

  // Member ids are stable and unique, so they disambiguate one row's menu from another's — same
  // reasoning as every other list on this workstream.
  const memberMenuBases = buildAgentListHandles({ prefix: "members-row", ids: members.map((member) => member.id) });

  return (
    <div className="page">
      <div className="page-header">
        <div className="page-header-text">
          <p className="page-kicker">{t("People")}</p>
          <h1 className="page-title">{t("Members")}</h1>
          <p className="page-description">
            {t(description)}
          </p>
        </div>
      </div>

      {members.length === 0 ? (
        <div className="card">
          <div className="empty-state">
            <p>{t("No members yet.")}</p>
            <p className="page-description">{t(emptyDescription)}</p>
          </div>
        </div>
      ) : (
      <div className="table-scroll">
      <table className="list-table">
        <thead>
          <tr>
            <th>{t("Email")}</th>
            <th>{t("Name")}</th>
            <th>{t("Status")}</th>
            <th>{t("Created")}</th>
            <th>{t("Actions")}</th>
          </tr>
        </thead>
        <tbody>
          {members.map((member, index) => (
            <MemberRow
              key={member.id}
              member={member}
              rowState={stateFor({ id: member.id })}
              isExpanded={expandedId === member.id}
              detail={detailById[member.id]}
              detailError={detailError}
              detailLoadingId={detailLoadingId}
              onToggleDetail={onToggleDetail}
              onResendSignInLink={onResendSignInLink}
              setConfirmingDisable={setConfirmingDisable}
              agentBase={memberMenuBases[index]!}
              t={t}
              translate={translate}
              renderServerLabel={renderServerLabel}
            />
          ))}
        </tbody>
      </table>
      </div>
      )}
      <ConfirmDialog
        cancelLabel={t("Cancel")}
        open={confirmingDisable !== null}
        agentHandle="members-disable"
        title={t("Disable this member?")}
        body={
          confirmingDisable ? (
            <p>
              {t("Disable")} &quot;{confirmingDisable.email}&quot;? {t("They will no longer be able to sign in.")}
            </p>
          ) : null
        }
        confirmLabel={t("Disable")}
        tone="warning"
        pending={confirmingDisable !== null && stateFor({ id: confirmingDisable.id }).disabling}
        onConfirm={confirmDisable}
        onCancel={() => setConfirmingDisable(null)}
      />
    </div>
  );
}

import { useId, type Dispatch, type FormEvent, type SetStateAction } from "react";
