}

interface UsersNoticesProps {
  toggleError: string | null;
  notice: string | null;
}

/** The Disable/Enable-toggle error banner and the reset-password success notice — extracted from
 *  `Users` verbatim. `Users` was still cyc 10 (over the tightened <=9/<=9 bar) with these two
 *  independent ternaries inline; moving them out is the same "extract to a top-level function"
 *  rule the rest of this pass follows. */
function UsersNotices({ toggleError, notice }: UsersNoticesProps) {
  return (
    <>
      {toggleError ? <div className="notice error">{toggleError}</div> : null}
      {notice ? <div className="notice">{notice}</div> : null}
    </>
  );
}

/** Assembles the expanded "Manage" panel's {@link UserManageController} from the screen-wide
 *  controller — extracted from `Users`' JSX in the complexity-ceiling pass (lot L182a) so its two
 *  `canGrant` ternaries count against this function, not `Users`. `roles`/`policies` are the
 *  already-loaded (non-null) lists `Users` narrowed before rendering the table. Without `canGrant`
 *  both grants are `null`, so the panel renders no grant controls. */
function userManageController({ controller, roles, policies }: {
  controller: UsersController; roles: AdminRole[]; policies: AdminPolicy[];
}): UserManageController {
  const { canGrant } = controller;
  return {
    error: controller.grantError,
    saving: controller.grantSaving,
    email: { value: controller.editEmail, set: controller.setEditEmail, saving: controller.emailSaving, save: controller.onSaveEmail },
    roleGrant: canGrant
      ? { options: roles, pendingId: controller.pendingRoleId, setPendingId: controller.setPendingRoleId, submit: controller.onAssignRole }
      : null,
    policyGrant: canGrant
      ? { options: policies, pendingId: controller.pendingPolicyId, setPendingId: controller.setPendingPolicyId, submit: controller.onAttachPolicy }
      : null,
  };
}

export function Users({ useUsersHook, port, translate: injectedTranslate, queryScope,
  openOwnPasswordReset, onOwnPasswordResetClosed, passwordResetNotice, renderServerLabel }: UsersProps) {
  // Widening `useUsers` to `UsersHook` is sound only through the `UsersProps` union: whenever
  // `useUsersHook` is omitted or typed as `useUsers`, `translate` is required, so the default hook
  // never runs without it. TypeScript cannot correlate the two destructured props itself.
  const useSelectedUsersHook = (useUsersHook ?? useUsers) as UsersHook;
  const controller = useSelectedUsersHook({ port, translate: injectedTranslate, queryScope }, {
    openOwnPasswordReset, onOwnPasswordResetClosed, passwordResetNotice,
  });
  const {
    users,
    roles,
    policies,
    canGrant,
    error,

    formOpen,
    setFormOpen,
    username,
    setUsername,
    email,
    setEmail,
    password,
    setPassword,
    saving,
    formError,
    onCreate,

    expandedId,
    toggleExpanded,

    toggleSavingId,
    toggleError,
    notice,

    confirmingDisable,
    setConfirmingDisable,
    requestDisable,
    confirmDisable,
    onToggleStatus,

    resetPasswordFor,
    setResetPasswordFor,
    newPassword,
    setNewPassword,
    passwordSaving,
    passwordError,
    setPasswordError,
    openResetPassword,
    confirmResetPassword,

    canManageUserTrash,
    rowCapabilities,
    ownProfile,
    renameUserHandler,
    changeUsername,
    confirmingDelete,
    setConfirmingDelete,
    requestDelete,
    deleteSaving,
    confirmDelete,

    t,
    translate,
  } = controller;

  if (error) return <div className="notice error">{error}</div>;
  if (!users || !roles || !policies) return <div className="notice">{t("Loading users…")}</div>;

  return (
    <div className="page">
      <UsersPageHeader formOpen={formOpen} setFormOpen={setFormOpen} t={t} />

      {formOpen ? (
        <NewUserForm
          username={username}
          setUsername={setUsername}
          email={email}
          setEmail={setEmail}
          password={password}
          setPassword={setPassword}
          saving={saving}
          formError={formError}
          onCreate={onCreate}
          t={t}
        />
      ) : null}

      <UsersNotices toggleError={toggleError} notice={notice} />

      <UsersTable
        users={users}
        ownPrincipalId={ownProfile?.principalId}
        roles={roles}
        policies={policies}
        showGrants={canGrant}
        actions={{
          expandedId,
          toggleExpanded,
          savingId: toggleSavingId,
          requestDisable,
          toggleStatus: onToggleStatus,
          openResetPassword,
          renameUserHandler,
          canDelete: canManageUserTrash,
          rowCapabilities,
          requestDelete,
        }}
        manage={userManageController({ controller, roles, policies })}
        t={t}
        translate={translate}
        renderServerLabel={renderServerLabel}
      />

      <UserDisableDialog
        confirmingDisable={confirmingDisable}
        setConfirmingDisable={setConfirmingDisable}
        toggleSavingId={toggleSavingId}
        confirmDisable={confirmDisable}
        t={t}
      />
      <UserDeleteDialog
        confirmingDelete={confirmingDelete}
        setConfirmingDelete={setConfirmingDelete}
        deleteSaving={deleteSaving}
        confirmDelete={confirmDelete}
        t={t}
      />
      <UserResetPasswordDialog
        resetPasswordFor={resetPasswordFor}
        setResetPasswordFor={setResetPasswordFor}
        newPassword={newPassword}
        setNewPassword={setNewPassword}
        passwordError={passwordError}
        setPasswordError={setPasswordError}
        passwordSaving={passwordSaving}
        confirmResetPassword={confirmResetPassword}
        t={t}
      />
      {changeUsername ? <ChangeUsernameDialog controller={changeUsername} translate={t} /> : null}
    </div>
  );
}
